package main;import("fmt";"io";"os";"strings";"mvdan.cc/sh/v3/syntax")
func main(){m:="fc";if len(os.Args)>1{m=os.Args[1]};s,_:=io.ReadAll(os.Stdin);src:=string(s);f,e:=syntax.NewParser().Parse(strings.NewReader(src),"");if e!=nil{fmt.Print(ck(src,e));return};if m=="fc"{syntax.Walk(f,func(n syntax.Node)bool{if d,ok:=n.(*syntax.FuncDecl);ok{fmt.Println(d.Name.Value)};return true})}else if m=="ca"{var w func(syntax.Node,string);w=func(n syntax.Node,path string){if n==nil{return};if c,ok:=n.(*syntax.CaseClause);ok{var pats []string;for _,it:=range c.Items{for _,p:=range it.Patterns{pats=append(pats,wordText(p))}};fmt.Println(path+":"+strings.Join(pats,","));for _,it:=range c.Items{for _,p:=range it.Patterns{np:=wordText(p);if path!=""{np=path+":"+np};for _,st:=range it.Stmts{w(st,np)}}};return};syntax.Walk(n,func(ch syntax.Node)bool{if ch==n{return true};w(ch,path);return false})};w(f,"")}else if m=="cb"{p:="";if len(os.Args)>2{p=os.Args[2]};syntax.Walk(f,func(n syntax.Node)bool{if c,ok:=n.(*syntax.CaseClause);ok{for _,it:=range c.Items{for _,pat:=range it.Patterns{if wordText(pat)==p{for _,st:=range it.Stmts{fmt.Print(src[st.Pos().Offset():st.End().Offset()])}}}}};return true})}else if m=="fb"{p:="";if len(os.Args)>2{p=os.Args[2]};syntax.Walk(f,func(n syntax.Node)bool{if d,ok:=n.(*syntax.FuncDecl);ok&&d.Name.Value==p{fmt.Print(src[d.Pos().Offset():d.End().Offset()])};return true})}else if m=="cu"{cu(f,src)}else if m=="ck"{}}
func ck(src string,e error)string{pos:=func(off int)(int,int){ln,col:=1,1;for i:=0;i<off&&i<len(src);i++{if src[i]=='\n'{ln++;col=1}else{col++}};return ln,col};var st []int;q:=byte(0);esc:=false;for i:=0;i<len(src);i++{c:=src[i];if esc{esc=false;continue};if c=='\\'&&q!='\''{esc=true;continue};if q!=0{if c==q{q=0};continue};if c=='\''||c=='"'{q=c;continue};switch c{case '(', '[', '{':st=append(st,i);case ')', ']', '}':m:=byte(0);if c==')'{m='('}else if c==']'{m='['}else{m='{'};if len(st)==0{ln,col:=pos(i);return fmt.Sprintf("<%d:%d unmatched %c\n",ln,col,c)};if src[st[len(st)-1]]!=m{ln,col:=pos(i);return fmt.Sprintf("<%d:%d mismatch %c\n",ln,col,c)};st=st[:len(st)-1]}};if q!=0{ln,col:=pos(len(src)-1);return fmt.Sprintf("<%d:%d unclosed %c\n",ln,col,q)};if len(st)>0{ln,col:=pos(st[len(st)-1]);return fmt.Sprintf("<%d:%d unclosed %c\n",ln,col,src[st[len(st)-1]])};pe,ok:=e.(syntax.ParseError);if !ok{return fmt.Sprintf("<%v\n",e)};ln,col:=int(pe.Pos.Line()),int(pe.Pos.Col());lines:=strings.Split(src,"\n");if ln-1>=len(lines){return fmt.Sprintf("<%d:%d %s\n",ln,col,pe.Text)};l:=lines[ln-1];a0:=col-40;if a0<0{a0=0};b0:=col+40;if b0>len(l){b0=len(l)};pre:="";if a0>0{pre="..."};post:="";if b0<len(l){post="..."};return fmt.Sprintf("<%d:%d %s\n%s%s%s\n%s^\n",ln,col,pe.Text,pre,l[a0:b0],post,strings.Repeat(" ",len(pre)+col-a0-1))}
func cu(f *syntax.File,src string){var cs []*syntax.CallExpr;c2s:=map[*syntax.CallExpr]*syntax.Stmt{};skip:=map[string]bool{"exit":true,"return":true,"echo":true,"[":true,"test":true,"shift":true,":":true};syntax.Walk(f,func(n syntax.Node)bool{if s,ok:=n.(*syntax.Stmt);ok{if c,ok:=s.Cmd.(*syntax.CallExpr);ok&&len(c.Args)>0&&!skip[wordText(c.Args[0])]{cs=append(cs,c);c2s[c]=s}};return true});var tp []*syntax.CallExpr;for _,c:=range cs{n:=false;for _,o:=range cs{if o!=c&&o.Pos().Offset()<=c.Pos().Offset()&&c.End().Offset()<=o.End().Offset(){n=true;break}};if !n{tp=append(tp,c)}};lm:=map[int][]*syntax.CallExpr{};for _,c:=range tp{l:=int(c.Pos().Line());lm[l]=append(lm[l],c)};total:=strings.Count(src,"\n")+1;if len(src)>0&&src[len(src)-1]=='\n'{total--};for i:=1;i<=total;i++{if c,ok:=lm[i];ok{var b strings.Builder;for j,x:=range c{if j>0{bet:=strings.TrimSpace(src[int(c[j-1].End().Offset()):int(x.Pos().Offset())]);if bet=="|"{b.WriteString("|")}else{b.WriteString("__")}};b.WriteString(strings.ReplaceAll(src[int(x.Pos().Offset()):int(x.End().Offset())],"\n"," "));if s,ok:=c2s[x];ok{for _,r:=range s.Redirs{b.WriteString(" ");b.WriteString(strings.ReplaceAll(src[int(r.Pos().Offset()):int(r.End().Offset())],"\n"," "))}}};fmt.Println(b.String())}else{fmt.Println()}}}
func wordText(w *syntax.Word)string{if w==nil{return ""};var b strings.Builder;for _,p:=range w.Parts{switch v:=p.(type){case *syntax.Lit:b.WriteString(v.Value);case *syntax.SglQuoted:b.WriteString("'");b.WriteString(v.Value);b.WriteString("'");case *syntax.DblQuoted:b.WriteString("\"");for _,q:=range v.Parts{if l,ok:=q.(*syntax.Lit);ok{b.WriteString(l.Value)}};b.WriteString("\"")}};return b.String()}
